@implements IAsyncDisposable
@inject IJSRuntime JS

<div @ref="_element"
     @onmousemove="OnUserActivity"
     @onkeydown="OnUserActivity"
     @onclick="OnUserActivity"
     @onscroll="OnUserActivity">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }
    [Parameter] public int TimeoutSeconds { get; set; } = 300;
    [Parameter] public EventCallback OnIdle { get; set; }
    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _element;
    private Timer? _timer;
    private bool _isIdle;

    protected override void OnInitialized()
    {
        ResetTimer();
    }

    private void OnUserActivity()
    {
        if (_isIdle)
        {
            _isIdle = false;
            OnActive.InvokeAsync();
        }

        ResetTimer();
    }

    private void ResetTimer()
    {
        _timer?.Dispose();
        _timer = new Timer(OnTimerElapsed, null,
            TimeSpan.FromSeconds(TimeoutSeconds), Timeout.InfiniteTimeSpan);
    }

    private void OnTimerElapsed(object? state)
    {
        InvokeAsync(() =>
        {
            _isIdle = true;
            OnIdle.InvokeAsync();
        });
    }

    public async ValueTask DisposeAsync()
    {
        if (_timer is not null)
        {
            await _timer.DisposeAsync();
            _timer = null;
        }
    }
}

